import{_ as i,l as c,o as a,c as r,v as s,p as n,x as o,d,i as p,S as l}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"namespaces","description":"","frontmatter":{"title":"namespaces","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/namespaces.md","filePath":"cs/namespaces.md","lastUpdated":1789023840000}'),m={name:"cs/namespaces.md"};function h(u,e,_,E,f,A){const t=c("Mermaid");return a(),r("div",null,[e[1]||(e[1]=s('<h1 id="namespaces" tabindex="-1">namespaces <a class="header-anchor" href="#namespaces" aria-label="Permalink to &quot;namespaces&quot;">​</a></h1><div class="epigraph"><p>命名空间让一组进程看见自己的 pid、挂载树、网络栈、IPC、UTS 名和用户 id 映射，而不是全局那一份。</p><footer>—— 据 Linux namespaces 文档；POSIX 未规定的 Linux 扩展，以内核文档为准</footer></div><p><a href="/cs/init-userspace">上一课</a>的 pid 1 是全局的。<a href="/cs/mount-super">挂载</a> 的树也是全局的。容器想「像一台机」又不跑第二次内核。缺口是 <strong>namespaces</strong>：隔离的是名字与视图，不是 CPU 时间配额（那是 cgroup）。本课合并六类常用空间，不当六篇词条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>chroot</code> 只改路径起点，pid 与网络仍全局。缺口：<code>clone</code>/<code>unshare</code> 带 <code>CLONE_NEWPID</code> 等标志，子进程成为该空间的 pid 1，看不见外面的进程表；<code>CLONE_NEWNS</code> 得到挂载副本；<code>CLONE_NEWNET</code> 有自己的网卡与回环；UTS 改 hostname；IPC 隔离 System V/POSIX 对象；user 命名空间映射容器内 uid 0 到外层非特权——机制课只讲映射存在，不讲如何打穿。</p><p><span class="marginnote">setns 加入已有空间。打开 <code>/proc/pid/ns/*</code> 可引用。本课不写逃逸步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>创建容器：先 user（若需要），再 pid/mnt/net 等，在新 pid 空间 exec 一个 init。该 init 只 wait 自己空间的孩子。挂载空间里可以有独立的 <code>/proc</code>，否则 pid 视图与 proc 不一致。与 <a href="/cs/file-table">文件表</a> 对照：fd 仍可在某些操作中指向外层对象，能力边界由实现规定，主干不展开利用。</p>',8)),(a(),n(l,null,{default:o(()=>[p(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLONE%5B%22clone%2Funshare%22%5D%20--%3E%20PIDNS%5B%22%E8%87%AA%E5%B7%B1%E7%9A%84%20pid%20%E6%A0%91%22%5D%0A%20%20CLONE%20--%3E%20MNT%5B%22%E8%87%AA%E5%B7%B1%E7%9A%84%E6%8C%82%E8%BD%BD%E6%A0%91%22%5D%0A%20%20CLONE%20--%3E%20NET%5B%22%E8%87%AA%E5%B7%B1%E7%9A%84%E7%BD%91%E7%BB%9C%E6%A0%88%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>命名空间把「全局内核表格」变成每组进程一份视图，让 <a href="/cs/vfs">VFS</a> 查找、<code>kill</code> 的 pid、<code>bind</code> 的端口号重新解释。内核仍是一份，特权环未变。这与虚拟机不同：没有第二套页表根给「客内核」。user ns 降低了「容器内 root」对外层的含义，安全课会再收。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 time 命名空间的全部细节。不保证所有资源都有命名空间（如某些设备号）。下一课：视图隔离不解 CPU/内存/IO 争用，需要分组记账与限制。</p><p>后课默认：名字可以按组切开。CPU 与内存配额，下一课 cgroups。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>namespaces 隔离 pid、挂载、网络等视图，内核仍一份。</li><li>容器内 pid 1 只覆盖该空间。</li><li>资源限制是 cgroup 的缺口。</li><li>出处：Linux <code>namespaces(7)</code>；Love 之后的内核文档；Tanenbaum <em>MOS</em> 对容器的讨论。</li></ul>',7))])}const N=i(m,[["render",h]]);export{T as __pageData,N as default};
